def maju_mundur_linear(x, w, b, t):
    d = w * x + b - t
    L = d ** 2
    dd = 2 * d
    return (float(L) + 0.0, float(dd * x) + 0.0, float(dd) + 0.0, float(dd * w) + 0.0)

