def linear_backward(W, x, dy):
    m, n = len(W), len(x)
    dW = [[dy[i] * x[j] for j in range(n)] for i in range(m)]
    dx = [sum(W[i][j] * dy[i] for i in range(m)) for j in range(n)]
    return (dW, dx)

