def mse_backward(y, t):
    n = len(y)
    galat = [a - b for a, b in zip(y, t)]
    loss = round(sum(e * e for e in galat) / n, 4)
    dy = [round(2 * e / n, 4) + 0.0 for e in galat]
    return (loss, dy)

