def urutan_topologis(graf):
    hasil, terlihat = [], set()
    def kunjungi(n):
        if n in terlihat:
            return
        terlihat.add(n)
        for p in graf[n]:
            kunjungi(p)
        hasil.append(n)
    for n in graf:
        kunjungi(n)
    return hasil

import math

class Value:
    def __init__(self, data, anak=()):
        self.data = data
        self.grad = 0.0
        self._back = lambda: None
        self._prev = set(anak)

    def __add__(self, o):
        o = o if isinstance(o, Value) else Value(o)
        out = Value(self.data + o.data, (self, o))
        def _b():
            self.grad += out.grad
            o.grad += out.grad
        out._back = _b
        return out

    __radd__ = __add__

    def __mul__(self, o):
        o = o if isinstance(o, Value) else Value(o)
        out = Value(self.data * o.data, (self, o))
        def _b():
            self.grad += o.data * out.grad
            o.grad += self.data * out.grad
        out._back = _b
        return out

    __rmul__ = __mul__

    def __neg__(self):
        return self * -1

    def __sub__(self, o):
        o = o if isinstance(o, Value) else Value(o)
        return self + (-o)

    def __pow__(self, n):
        out = Value(self.data ** n, (self,))
        def _b():
            self.grad += n * self.data ** (n - 1) * out.grad
        out._back = _b
        return out

    def tanh(self):
        t = math.tanh(self.data)
        out = Value(t, (self,))
        def _b():
            self.grad += (1 - t * t) * out.grad
        out._back = _b
        return out

    def backward(self):
        urut, terlihat = [], set()
        def bangun(v):
            if v not in terlihat:
                terlihat.add(v)
                for p in v._prev:
                    bangun(p)
                urut.append(v)
        bangun(self)
        self.grad = 1.0
        for v in reversed(urut):
            v._back()
